using System.Windows.Media;

namespace YTFE.Services;

/// <summary>
/// Logo de un sitio: trazo vectorial (cuadrícula 24x24, de Simple Icons, licencia CC0) y color de marca.
/// Sin trazo = se dibuja la inicial del nombre sobre el color de marca.
/// </summary>
public sealed record SiteLogo(string? PathData, string Color)
{
    public Brush Brush => (Brush)new BrushConverter().ConvertFromString(Color)!;
    public Geometry? Geometry => PathData is null ? null : System.Windows.Media.Geometry.Parse(PathData);
}

